('Annual Tech Fest 2026', 'Two days of coding contests, workshops and talks.', 'Main Auditorium', '2026-12-12', '10:00 AM', 's_featured1.png', 120),
('Diwali Mela 2026', 'Food stalls, rangoli competition, kids games and a cultural programme in the evening. Entry is free but seats for the evening show are limited, so book in advance.', 'Community Ground, Sector 12', '2026-11-07', '5:00 PM', 'about1.png', 300),
('Wedding Planning Workshop', 'A two hour session for couples and families planning a wedding in the coming season. We will cover budgets, choosing a venue, vendor contracts and building a timeline for the functions. Tea and snacks included.', 'Eventify Studio, MG Road', '2026-11-15', '11:00 AM', 'services2.png', 40),
('Sufi Night at the Lawns', 'An evening of live sufi and ghazal music under the open sky. Dinner counters open at 7 PM and the performance starts at 8 PM.', 'Open Lawns, City Club', '2026-11-21', '7:00 PM', 's_featured2.png', 200);
