INSERT INTO contact (firstName, lastName, email, phone, message, actionTaken, createdAt) VALUES
('Priya', 'Sharma', 'priya.sharma@example.com', '9810098100', 'Hi, my sister is getting married in February and we are looking for someone to handle the haldi, mehendi and sangeet. Around 250 guests. Can we set up a call this week?', false, '2026-10-27 19:12:00'),
('Arjun', 'Mehta', 'arjun.mehta@example.com', '9876012340', 'We are planning our annual sales meet for about 120 people in January. Need a venue outside the city with stay for two nights. Please share some options and a rough budget.', false, '2026-10-26 11:40:00'),
('Sanya', 'Khanna', 'sanya.khanna@example.com', '9899011223', 'Looking to plan a surprise 50th birthday party for my father. Small gathering of 40 people at home or a nearby restaurant. Do you take events this small?', false, '2026-10-25 22:05:00'),
('Rahul', 'Iyer', 'rahul.iyer@example.com', '9845012345', 'I am from the cultural committee of our college. We want help with sound, lights and stage for our fest pro-night in March. Expected crowd is around 2000.', true, '2026-10-22 14:30:00'),
('Meera', 'Pillai', 'meera.pillai@example.com', '9123409876', 'Can you organise a product launch for a skincare brand? We are thinking of an evening event with influencers and media, around 80 people.', true, '2026-10-18 16:55:00'),
('Karan', 'Chopra', 'karan.chopra@example.com', '9811122233', 'Do you do destination weddings in Udaipur or Jaipur? Dates would be around November next year. Please let me know your packages.', false, '2026-10-28 09:20:00'),
('Divya', 'Reddy', 'divya.reddy@example.com', '9700012345', 'We want to book a team outing with some fun activities for 35 people from our office. One day, preferably on a Saturday.', true, '2026-10-15 12:10:00'),
('Nikhil', 'Bhatia', 'nikhil.bhatia@example.com', '9650098765', 'Hello, what is the price for a basic birthday decoration package for a 5 year old? Theme would be dinosaurs.', true, '2026-10-12 18:45:00');
