USE eventify;



SELECT id, r.name, r.email, r.phone, r.seats, r.createdAt FROM events e
JOIN (
  SELECT 'Diwali Mela 2026' AS title, 'Rohit Verma' AS name, 'rohit.verma@example.com' AS email, '9810012345' AS phone, 4 AS seats, '2026-10-20 18:42:00' AS createdAt
  UNION ALL SELECT 'Diwali Mela 2026', 'Sneha Kapoor', 'sneha.k@example.com', '9876501234', 2, '2026-10-21 10:15:00'
  UNION ALL SELECT 'Diwali Mela 2026', 'Mohammed Arif', 'arif.m@example.com', '9899123456', 5, '2026-10-23 20:05:00'
  UNION ALL SELECT 'Diwali Mela 2026', 'Kavya Nair', 'kavya.nair@example.com', '9123456780', 3, '2026-10-26 13:30:00'
  UNION ALL SELECT 'Wedding Planning Workshop', 'Ananya Gupta', 'ananya.gupta@example.com', '9812233445', 2, '2026-10-22 11:48:00'
  UNION ALL SELECT 'Wedding Planning Workshop', 'Vikram Singh', 'vikram.singh@example.com', '9998877665', 2, '2026-10-24 16:20:00'
  UNION ALL SELECT 'Wedding Planning Workshop', 'Pooja Mehra', 'pooja.mehra@example.com', '9871122334', 1, '2026-10-27 09:05:00'
  UNION ALL SELECT 'Sufi Night at the Lawns', 'Aditya Rao', 'aditya.rao@example.com', '9845098450', 2, '2026-10-25 21:10:00'
  UNION ALL SELECT 'Sufi Night at the Lawns', 'Neha Joshi', 'neha.joshi@example.com', '9765432109', 4, '2026-10-26 19:45:00'
  UNION ALL SELECT 'Sufi Night at the Lawns', 'Farhan Qureshi', 'farhan.q@example.com', '9811198111', 2, '2026-10-28 08:30:00'
  UNION ALL SELECT 'Annual Tech Fest 2026', 'Ishaan Malhotra', 'ishaan.m@example.com', '9650011223', 1, '2026-10-19 15:00:00'
  UNION ALL SELECT 'Annual Tech Fest 2026', 'Riya Bansal', 'riya.bansal@example.com', '9560044556', 3, '2026-10-27 17:25:00'
) r ON r.title = e.title;

